import base64
from .i_image_capture_service import CapturedImage, IImageCaptureService


class StubImageCaptureService(IImageCaptureService):
    def capture(self) -> CapturedImage:
        image = base64.b64decode(
            ''
        )

        return CapturedImage(image, image, (), 320, 240, "2026-01-01T00:00:00+00:00",
                             b'{"contours": [], "summary": {}}', image)

    def save_image(self, capture: CapturedImage) -> str:
        print("[ImageCapture] Saved stub image")
        return "stub/capture_pair"

    def output_directory(self) -> str:
        return "stub"
